		/** 
		 * Tests creating a new Attestation.
		 */
		public void testCreate() throws Throwable {
			LOGGER.info( "\n======== CREATE ======== ");
			LOGGER.info( "-- Attempting to create a Attestation");

			StringBuilder msg = new StringBuilder( "-- Failed to create a Attestation" );

			try {            
				Attestation entity = AttestationService.getAttestationInstance().createAttestation( generateNewEntity() );
				thePrimaryKey = entity.getAttestationId();
				LOGGER.info( "-- Successfully created a Attestation with primary key" + thePrimaryKey );
			}
			catch (Exception e) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests reading a Attestation. 
		 */
		public Attestation testRead() throws Throwable {
			LOGGER.info( "\n======== READ ======== ");
			LOGGER.info( "-- Reading a previously created Attestation" );

			Attestation entity = null;
			StringBuilder msg = new StringBuilder( "-- Failed to read Attestation with primary key" );
			msg.append( thePrimaryKey );
			
			AttestationFetchOneSummary fetchOneSummary = new AttestationFetchOneSummary( thePrimaryKey );

			try {
				entity = AttestationService.getAttestationInstance().getAttestation( fetchOneSummary );

				assertNotNull( entity,msg.toString() );

				LOGGER.info( "-- Successfully found Attestation " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
			
			return entity;
		}

		/** 
		 * Tests updating a Attestation.
		 */
		public void testUpdate() throws Throwable {
			LOGGER.info( "\n======== UPDATE ======== ");
			LOGGER.info( "-- Attempting to update a Attestation." );

			StringBuilder msg = new StringBuilder( "Failed to update a Attestation : " );        
			Attestation entity = null;

			try {            
				entity = testRead();

				assertNotNull( entity, msg.toString() );

				LOGGER.info( "-- Now updating the created Attestation." );

				// for use later on...
				thePrimaryKey = entity.getAttestationId();

				AttestationService proxy = AttestationService.getAttestationInstance();            
				proxy.updateAttestation( entity );   

				LOGGER.info( "-- Successfully saved Attestation - " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : primarykey = " + thePrimaryKey + " : entity-" +  entity + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests deleting a Attestation.
		 */
		public void testDelete() throws Throwable {
			LOGGER.info( "\n======== DELETE ======== ");
			LOGGER.info( "-- Deleting a previously created Attestation." );

			try{
			    Attestation entity = testRead(); 
				AttestationService.getAttestationInstance().delete( entity );

				LOGGER.info( "-- Successfully deleted Attestation with primary key " + thePrimaryKey );            
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( "-- Failed to delete Attestation with primary key " + thePrimaryKey );

				throw e;
			}
		}

		/**
		 * Tests getting all Attestations.
		 */
		public void testGetAll() throws Throwable {    
			LOGGER.info( "======== GETALL ======== ");
			LOGGER.info( "-- Retrieving Collection of Attestations:" );

			StringBuilder msg = new StringBuilder( "-- Failed to get all Attestation : " );        
			List<Attestation> collection  = null;

			try {
				// call the static get method on the AttestationService
				collection = AttestationService.getAttestationInstance().getAllAttestation();

				if ( collection == null || collection.size() == 0 ) {
					LOGGER.warning( unexpectedErrorMsg );
					LOGGER.warning( msg.toString() + " Empty collection returned."  );
				}
				else {
					// Now print out the values
					Attestation entity = null;            
					Iterator<Attestation> iter = collection.iterator();
					int index = 1;

					while( iter.hasNext() ) {
						// Retrieve the entity   
						entity = iter.next();

						assertNotNull( entity,"-- null entity in Collection." );
						assertNotNull( entity.getAttestationId(), "-- entity in Collection has a null primary key" );        

						LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
						index++;
					}
				}
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

